// ─── Client Message Thread (Public) ───────────────────────────────────────────
function ClientMessageThread({ deliveryRequest, plateNumber }) {
  const [messages, setMessages] = useState([]);
  const [newMsg, setNewMsg] = useState("");
  const [sending, setSending] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const bottomRef = useRef();

  const loadMessages = useCallback(async () => {
    if (!deliveryRequest?.id) return;
    const { data } = await supabase.from("delivery_messages")
      .select("*")
      .eq("request_id", deliveryRequest.id)
      .order("sent_at", { ascending: true });
    if (data) { setMessages(data); setLoaded(true); }
  }, [deliveryRequest?.id]);

  useEffect(() => { loadMessages(); }, [loadMessages]);

  // Real-time new messages
  useEffect(() => {
    if (!deliveryRequest?.id) return;
    const channel = supabase.channel("client-msgs-" + deliveryRequest.id)
      .on("postgres_changes", { event: "INSERT", schema: "public", table: "delivery_messages",
        filter: "request_id=eq." + deliveryRequest.id }, (payload) => {
        setMessages(prev => [...prev, payload.new]);
      }).subscribe();
    return () => supabase.removeChannel(channel);
  }, [deliveryRequest?.id]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = async () => {
    if (!newMsg.trim() || sending || !deliveryRequest?.id) return;
    setSending(true);
    const { error } = await supabase.from("delivery_messages").insert({
      request_id:  deliveryRequest.id,
      plate_number: plateNumber,
      sender_type: "client",
      sender_name: deliveryRequest.claimant_name || "Client",
      message:     newMsg.trim(),
      is_read:     false,
    });
    if (!error) setNewMsg("");
    else alert("Failed to send message. Please try again.");
    setSending(false);
  };

  if (!deliveryRequest?.id) return null;

  return (
    <div className="bg-white border border-gray-200 rounded-2xl overflow-hidden">
      <div className="bg-blue-900 px-4 py-3 flex items-center gap-2">
        <Globe size={15} className="text-blue-300"/>
        <p className="text-white text-sm font-bold">Message LTO Binangonan Staff</p>
        <span className="ml-auto text-xs text-blue-300">Plate: {plateNumber}</span>
      </div>
      {/* Messages */}
      <div className="p-4 space-y-3 max-h-64 overflow-y-auto bg-gray-50">
        {!loaded && <p className="text-xs text-gray-400 text-center py-4">Loading messages...</p>}
        {loaded && messages.length === 0 && (
          <div className="text-center py-6">
            <p className="text-xs text-gray-400 font-semibold">No messages yet</p>
            <p className="text-xs text-gray-400 mt-1">Send a message to LTO staff about your delivery request.</p>
          </div>
        )}
        {messages.map(m => (
          <div key={m.id} className={`flex ${m.sender_type==="client" ? "justify-end" : "justify-start"}`}>
            <div className={`max-w-[80%] rounded-2xl px-4 py-2.5 ${
              m.sender_type==="client"
                ? "bg-blue-700 text-white rounded-br-sm"
                : "bg-white border border-gray-200 text-gray-800 rounded-bl-sm"
            }`}>
              {m.sender_type==="staff" && (
                <p className="text-xs font-bold text-blue-600 mb-1">{m.sender_name}</p>
              )}
              <p className="text-sm leading-relaxed">{m.message}</p>
              <p className={`text-xs mt-1 ${m.sender_type==="client" ? "text-blue-200" : "text-gray-400"}`}>
                {new Date(m.sent_at).toLocaleString("en-PH",{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"})}
              </p>
            </div>
          </div>
        ))}
        <div ref={bottomRef}/>
      </div>
      {/* Input */}
      <div className="p-3 border-t border-gray-100 flex gap-2">
        <input
          value={newMsg}
          onChange={e=>setNewMsg(e.target.value)}
          onKeyDown={e=>{ if(e.key==="Enter" && !e.shiftKey) { e.preventDefault(); sendMessage(); } }}
          placeholder="Type your message..."
          className="flex-1 border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-blue-500"
        />
        <button onClick={sendMessage} disabled={sending || !newMsg.trim()}
          className="px-4 py-2.5 bg-blue-700 text-white rounded-xl hover:bg-blue-800 disabled:bg-gray-200 disabled:text-gray-400 text-sm font-bold flex items-center gap-1.5 shrink-0">
          {sending ? <Loader size={14} className="animate-spin"/> : <><Globe size={14}/> Send</>}
        </button>
      </div>
    </div>
  );
}

