function PhPlate({ number, color="white", small=false }) {
  const isWhite = color === "white";
  const bg = isWhite ? "#ffffff" : "#22c55e";
  const txt = isWhite ? "#111827" : "#fff";
  const border = isWhite ? "#d1d5db" : "#15803d";
  const strip = isWhite ? "#1d4ed8" : "#166534";
  const stripTxt = "#fff";
  const sz = small ? 0.7 : 1;
  const w = 220 * sz, h = 56 * sz, r = 6 * sz;
  const fs = small ? 18 : 26;
  const fsLabel = small ? 6 : 8;
  return (
    <svg width={w} height={h} viewBox={`0 0 220 56`} xmlns="http://www.w3.org/2000/svg" style={{filter:"drop-shadow(0 4px 12px rgba(0,0,0,0.25))"}}>
      <rect x="1" y="1" width="218" height="54" rx={r} fill={bg} stroke={border} strokeWidth="2"/>
      <rect x="1" y="1" width="218" height="13" rx={r} fill={strip}/>
      <rect x="1" y="10" width="218" height="4" fill={strip}/>
      <text x="110" y="11" textAnchor="middle" fill={stripTxt} fontSize={fsLabel} fontWeight="700" fontFamily="Arial,sans-serif" letterSpacing="2">PHILIPPINES</text>
      <text x="110" y="45" textAnchor="middle" fill={txt} fontSize={fs} fontWeight="900" fontFamily="Arial Black,Arial,sans-serif" letterSpacing="4">{number}</text>
    </svg>
  );
}

